// Reponse pour Archi : basee sur le VRAI resultat de l'audit
const audit = $('Lire audit').first().json.audit || {};
const plan = $('Lire plan').first().json;
const ok = audit.ok === true;
const problemes = (audit.problemes || []).slice();
if (audit.erreur) problemes.push(audit.erreur);
const d = audit.dimensions_mm;
const dims = d ? `${d.x} sur ${d.y} sur ${d.z} millimètres` : 'inconnu';
const hyp = String(plan.hypotheses || '').trim();

const phrase = ok
  ? `C'est fait BOSS, la pièce ${plan.nom_base} est générée et enregistrée. Encombrement : ${dims}.` + (hyp ? ` Hypothèses : ${hyp}` : '')
  : `Attention BOSS, la pièce ${plan.nom_base} est enregistrée mais le contrôle a trouvé un problème : ${problemes.join(' ; ') || 'résultat illisible'}. Ne l'imprime pas telle quelle.`;

// Fiche ecrite envoyee avec l'apercu sur Telegram
const NOMS = { a:'aile au sol', b:'aile verticale', l:'largeur', ep:'épaisseur', trou:'perçages', n:'trous par aile', renfort:'renfort',
  tige:'diamètre de tige', tige_l:'longueur de tige', pas:'pas', filet:'filetage', w:'largeur intérieure', h:'hauteur', p:'profondeur',
  L:'longueur', nx:'trous en longueur', ny:'trous en largeur', marge:'marge', h1:'bout fin', h2:'bout épais', d_ext:'diamètre extérieur',
  d_int:'diamètre intérieur', d_roul:'diamètre roulement', h_roul:'épaisseur roulement', d_arbre:'diamètre arbre', cote:'côté moteur',
  entraxe:'entraxe', d_centre:'diamètre centrage', base:'base', trou_m:'trous moteur', vis:'trou de vis', d:'diamètre', gorge:'gorge', m:'module', z:'dents' };
const SANS_MM = ['n', 'nx', 'ny', 'z', 'm'];
const val = (k, v) => typeof v === 'boolean' || v === 'true' || v === 'false' ? ((v === true || v === 'true') ? 'oui' : 'non') : v + (SANS_MM.includes(k) ? '' : ' mm');
const compris = plan.params
  ? Object.entries(plan.params).map(([k, v]) => (NOMS[k] || k) + ' ' + val(k, v)).join(', ')
  : 'assemblage libre de volumes';
const fmt3 = o => o ? `${o.x} x ${o.y} x ${o.z} mm` : '?';
const fiche = [
  `Pièce : ${plan.nom_base} (${plan.forme})`,
  `J'ai compris : ${compris}`,
  `Attendu : ${fmt3(audit.attendu_mm)}  |  Obtenu : ${fmt3(audit.dimensions_mm)}`,
  `Contrôle : ${ok ? 'OK' : 'À VÉRIFIER - ' + problemes.join(' ; ')}`,
  hyp ? `Hypothèses : ${hyp}` : ''
].filter(Boolean).join('\n').slice(0, 1000);

return [{ json: {
  statut: ok ? 'OK' : 'A_VERIFIER',
  phrase_pour_utilisateur: phrase,
  fiche,
  fichier: plan.nom_base,
  forme: plan.forme,
  hypotheses: hyp,
  audit
} }];

const brut = ($input.first().json.stdout || '').trim();
let audit;
try {
  audit = JSON.parse(brut);
} catch (e) {
  audit = { ok: false, erreur: 'sortie illisible : ' + brut + ' / ' + ($input.first().json.stderr || '') };
}

// Comparaison avec l'encombrement attendu d'apres le plan
const att = $('Lire plan').first().json.attendu;
if (att && audit.dimensions_mm) {
  const obt = [audit.dimensions_mm.x, audit.dimensions_mm.y, audit.dimensions_mm.z];
  audit.attendu_mm = { x: +att[0].toFixed(2), y: +att[1].toFixed(2), z: +att[2].toFixed(2) };
  audit.problemes = audit.problemes || [];
  'XYZ'.split('').forEach((axe, i) => {
    const tol = Math.max(0.6, att[i] * 0.02);
    if (Math.abs(obt[i] - att[i]) > tol) {
      audit.problemes.push('cote en ' + axe + ' : attendu ' + att[i].toFixed(1) + ' mm, obtenu ' + obt[i] + ' mm');
    }
  });
  audit.ok = audit.ok && audit.problemes.length === 0;
}
return [{ json: { audit } }];

// ============================================
//  ASSEMBLER SCAD - catalogue construction + mécanique
// ============================================

// 1. Lire le JSON renvoyé par le Concepteur IA
const brut = $input.first().json.choices[0].message.content;
const m = brut.match(/\{[\s\S]*\}/);
if (!m) throw new Error('Le concepteur n a pas renvoye de JSON');
const plan = JSON.parse(m[0]);

const forme = (plan.forme || 'libre').toLowerCase();
let hyp = plan.hypotheses || '';

// 2. Bibliothèque de formes (OpenSCAD)
const LIB = `
// ---------- CONSTRUCTION / CHARPENTE ----------

module equerre(a,b,l,ep,trou,n,renfort,l_sol=0,l_bout=0){
  ls = l_sol > 0 ? l_sol : l;
  lb = l_bout > 0 ? l_bout : ls;
  ys = renfort ? [l/4, 3*l/4] : [l/2];
  g = min(a,b)*0.6;
  difference(){
    union(){
      linear_extrude(ep) polygon([[0,l/2-ls/2],[a,l/2-lb/2],[a,l/2+lb/2],[0,l/2+ls/2]]);
      cube([ep,l,b]);
      if (renfort)
        translate([0,(l+ep)/2,0]) rotate([90,0,0])
          linear_extrude(ep) polygon([[0,0],[g,0],[0,g]]);
    }
    if (n > 0) for (y=ys) for (i=[1:n])
      translate([ep+(a-ep)*i/(n+1), y, -1]) cylinder(d=trou, h=ep+2);
    if (n > 0) for (y=ys) for (i=[1:n])
      translate([-1, y, ep+(b-ep)*i/(n+1)]) rotate([0,90,0]) cylinder(d=trou, h=ep+2);
  }
}

module sabot(w,h,p,ep,a,trou,n){
  difference(){
    union(){
      translate([-w/2-ep,0,0]) cube([w+2*ep,p,ep]);
      translate([-w/2-ep,0,0]) cube([ep,p,h]);
      translate([w/2,0,0]) cube([ep,p,h]);
      translate([-w/2-ep-a,0,0]) cube([a+ep,ep,h]);
      translate([w/2,0,0]) cube([a+ep,ep,h]);
    }
    for (s=[-1,1]) for (i=[1:n])
      translate([s*(w/2+ep+a/2), -1, h*i/(n+1)]) rotate([-90,0,0]) cylinder(d=trou, h=ep+2);
  }
}

module plaque(L,l,ep,trou,nx,ny,marge){
  difference(){
    cube([L,l,ep]);
    for (i=[0:nx-1]) for (j=[0:ny-1])
      translate([
        nx>1 ? marge+i*(L-2*marge)/(nx-1) : L/2,
        ny>1 ? marge+j*(l-2*marge)/(ny-1) : l/2,
        -1]) cylinder(d=trou, h=ep+2);
  }
}

module gousset(a,b,ep,trou){
  difference(){
    linear_extrude(ep) polygon([[0,0],[a,0],[0,b]]);
    for (pt=[[a*0.5,b*0.15],[a*0.15,b*0.5],[a*0.15,b*0.15]])
      translate([pt[0],pt[1],-1]) cylinder(d=trou, h=ep+2);
  }
}

module cale(l,w,h1,h2){
  translate([0,w,0]) rotate([90,0,0])
    linear_extrude(w) polygon([[0,0],[l,0],[l,h2],[0,h1]]);
}

module entretoise(d_ext,d_int,h){
  difference(){
    cylinder(d=d_ext, h=h);
    translate([0,0,-1]) cylinder(d=d_int, h=h+2);
  }
}

module etrier(w,h,l,ep,a,trou){
  difference(){
    translate([0,l,0]) rotate([90,0,0]) linear_extrude(l) union(){
      translate([-w/2-ep-a,0]) square([a,ep]);
      translate([w/2+ep,0]) square([a,ep]);
      translate([-w/2-ep,0]) square([ep,h+ep]);
      translate([w/2,0]) square([ep,h+ep]);
      translate([-w/2-ep,h]) square([w+2*ep,ep]);
    }
    for (s=[-1,1])
      translate([s*(w/2+ep+a/2), l/2, -1]) cylinder(d=trou, h=ep+2);
  }
}

function _prof_filet(t, rmin, rmax) =
  t < 1/8  ? rmin :
  t < 7/16 ? rmin + (rmax-rmin)*(t-1/8)/(5/16) :
  t < 9/16 ? rmax :
  t < 7/8  ? rmax - (rmax-rmin)*(t-9/16)/(5/16) : rmin;

// Filetage ISO exterieur (pas a droite), jeu de 0.2 mm pour l'impression
module filet_ext(d, pas, h){
  nf = 48;
  rmax = d/2 - 0.1;
  rmin = rmax - 0.625*0.866*pas;
  pts = [for (i=[0:nf-1]) let(an=i*360/nf, r=_prof_filet(i/nf, rmin, rmax)) [r*cos(an), r*sin(an)]];
  intersection(){
    linear_extrude(height=h, twist=-360*h/pas, slices=ceil(h/pas)*16) polygon(pts);
    union(){
      cylinder(r=rmax+1, h=h-pas*0.6);
      translate([0,0,h-pas*0.6]) cylinder(r1=rmax, r2=rmin, h=pas*0.6);
    }
  }
}

// Equerre dont l'aile verticale est prolongee par une tige (filetee ou lisse)
module equerre_tige(a,b,l,ep,trou,n,renfort,tige,tige_l,pas,filet,l_sol=0,l_bout=0){
  tr = max(tige, ep);
  lt = max(tige_l - tr + 0.5, pas*2);
  union(){
    equerre(a,b,l,ep,trou,n,renfort,l_sol,l_bout);
    hull(){
      translate([0,0,b-0.5]) cube([ep,l,0.5]);
      translate([ep/2,l/2,b+tr-0.01]) cylinder(d=tige, h=0.01);
    }
    translate([ep/2,l/2,b+tr-0.5])
      if (filet) filet_ext(tige, pas, lt);
      else cylinder(d=tige-0.2, h=lt);
  }
}

// ---------- ASSEMBLAGE ET MAISON ----------

module plaque_t(L,H,l,ep,trou,n){
  difference(){
    union(){
      translate([0,H-l,0]) cube([L,l,ep]);
      translate([L/2-l/2,0,0]) cube([l,H,ep]);
    }
    translate([L/2,H-l/2,-1]) cylinder(d=trou, h=ep+2);
    if (n > 0) for (i=[1:2*n]) translate([L*i/(2*n+1), H-l/2, -1]) cylinder(d=trou, h=ep+2);
    if (n > 0) for (i=[1:n]) translate([L/2, (H-l)*i/(n+1), -1]) cylinder(d=trou, h=ep+2);
  }
}

module plaque_l(a,b,l,ep,trou,n){
  difference(){
    union(){
      cube([a,l,ep]);
      cube([l,b,ep]);
    }
    translate([l/2,l/2,-1]) cylinder(d=trou, h=ep+2);
    if (n > 0) for (i=[1:n]) translate([l+(a-l)*i/(n+1), l/2, -1]) cylinder(d=trou, h=ep+2);
    if (n > 0) for (i=[1:n]) translate([l/2, l+(b-l)*i/(n+1), -1]) cylinder(d=trou, h=ep+2);
  }
}

// Crochet mural, modelise couche sur le cote (meilleure solidite a l'impression)
module crochet(H,l,ep,saillie,pointe,trou,n){
  difference(){
    linear_extrude(l) union(){
      square([ep,H]);
      square([ep+saillie,ep]);
      translate([saillie,0]) square([ep,max(pointe,ep)]);
      polygon([[ep-0.01,ep-0.01],[ep+ep*1.5,ep-0.01],[ep-0.01,ep+ep*1.5]]);
    }
    if (n > 0) for (i=[1:n])
      translate([-1, ep+(H-ep)*i/(n+1), l/2]) rotate([0,90,0]) cylinder(d=trou, h=ep+2);
  }
}

// Pontet / demi-collier a visser pour tube
module support_tube(d_tube,ep,l,aile,trou){
  dt = d_tube + 0.4;
  R = dt/2 + ep;
  difference(){
    translate([0,l,0]) rotate([90,0,0]) linear_extrude(l) intersection(){
      translate([-R-aile-1,0]) square([2*R+2*aile+2, dt+2*ep]);
      difference(){
      union(){
        translate([0,dt/2]) circle(r=R);
        translate([-R,0]) square([2*R, dt/2]);
        translate([-R-aile,0]) square([2*R+2*aile, ep]);
      }
      translate([0,dt/2]) circle(d=dt);
      translate([-dt/2,-1]) square([dt, dt/2+1]);
      }
    }
    for (s=[-1,1]) translate([s*(R+aile/2), l/2, -1]) cylinder(d=trou, h=ep+2);
  }
}

// Chape en U avec axe traversant
module chape(e,h,l,ep,d_axe,trou){
  difference(){
    union(){
      cube([e+2*ep, l, ep]);
      for (x=[0, e+ep]) translate([x,0,0]) rotate([90,0,90]) linear_extrude(ep)
        hull(){ square([l,0.01]); translate([l/2,h-l/2]) circle(d=l); }
    }
    translate([-1, l/2, h-l/2]) rotate([0,90,0]) cylinder(d=d_axe, h=e+2*ep+2);
    translate([(e+2*ep)/2, l/2, -1]) cylinder(d=trou, h=ep+2);
  }
}

// Pied reglable : semelle avec ecrou prisonnier (ecrou insere par le dessus)
module pied_reglable(d,h,vis){
  s = vis==5 ? 8 : vis==6 ? 10 : vis==8 ? 13 : vis==10 ? 17 : vis*1.6+0.4;
  e_nut = vis*0.8 + 0.4;
  difference(){
    cylinder(d1=d, d2=d*0.8, h=h);
    translate([0,0,h-e_nut]) cylinder(d=(s+0.4)/cos(30), h=e_nut+1, $fn=6);
    translate([0,0,1.5]) cylinder(d=vis+0.5, h=h);
  }
}

// Boite ouverte (le couvercle est une piece a part)
module boite(L,l,h,ep,fond){
  difference(){
    cube([L,l,h]);
    translate([ep,ep,fond]) cube([L-2*ep, l-2*ep, h]);
  }
}

// Couvercle de la boite, imprime a l'envers (levre vers le haut)
module couvercle(L,l,ep,ep_c,levre,jeu){
  union(){
    cube([L,l,ep_c]);
    translate([ep+jeu, ep+jeu, ep_c-0.01]) difference(){
      cube([L-2*ep-2*jeu, l-2*ep-2*jeu, levre]);
      translate([ep,ep,-1]) cube([L-4*ep-2*jeu, l-4*ep-2*jeu, levre+2]);
    }
  }
}

// Clip pour tube, ouvert sur le dessus, avec patte a visser
module clip_tube(d_tube,ep,l,aile,trou){
  dt = d_tube + 0.3;
  R = dt/2 + ep;
  difference(){
    translate([0,l,0]) rotate([90,0,0]) linear_extrude(l) difference(){
      union(){
        translate([0,R]) circle(r=R);
        translate([-R-aile,0]) square([2*R+2*aile, ep]);
      }
      translate([0,R]) circle(d=dt);
      translate([0,R]) polygon([[0,0],[-(R+1)*tan(55),R+1],[(R+1)*tan(55),R+1]]);
    }
    for (s=[-1,1]) translate([s*(R+aile/2), l/2, -1]) cylinder(d=trou, h=ep+2);
  }
}

// ---------- MÉCANIQUE ----------

module palier(d_roul,h_roul,d_arbre,L,l,ep,trou){
  h = h_roul + ep;
  difference(){
    translate([-L/2,-l/2,0]) cube([L,l,h]);
    translate([0,0,ep]) cylinder(d=d_roul+0.2, h=h_roul+1);
    translate([0,0,-1]) cylinder(d=d_arbre+2, h=h+2);
    for (x=[-1,1]) translate([x*(L/2-trou*1.5),0,-1]) cylinder(d=trou, h=h+2);
  }
}

module support_moteur(cote,entraxe,d_centre,ep,base,trou_m,trou){
  difference(){
    union(){
      translate([-cote/2,0,0]) cube([cote,base,ep]);
      translate([-cote/2,0,0]) cube([cote,ep,cote+ep]);
    }
    translate([0,-1,ep+cote/2]) rotate([-90,0,0]) cylinder(d=d_centre, h=ep+2);
    for (x=[-1,1]) for (z=[-1,1])
      translate([x*entraxe/2,-1,ep+cote/2+z*entraxe/2]) rotate([-90,0,0]) cylinder(d=trou_m, h=ep+2);
    for (x=[-1,1]) translate([x*cote/4, ep+(base-ep)/2, -1]) cylinder(d=trou, h=ep+2);
  }
}

module collier(d_arbre,d_ext,h,vis){
  difference(){
    cylinder(d=d_ext, h=h);
    translate([0,0,-1]) cylinder(d=d_arbre+0.2, h=h+2);
    translate([0,0,h/2]) rotate([0,90,0]) cylinder(d=vis, h=d_ext);
  }
}

module poulie(d,h,d_arbre,gorge){
  difference(){
    cylinder(d=d, h=h);
    translate([0,0,-1]) cylinder(d=d_arbre+0.2, h=h+2);
    translate([0,0,h/2]) rotate_extrude() translate([d/2,0]) circle(d=gorge);
  }
}

module engrenage(m,z,h,d_arbre){
  rp = m*z/2; ra = rp+m; rf = rp-1.25*m;
  t1 = PI*m/4*1.3; t2 = PI*m/4*0.5;
  difference(){
    linear_extrude(h) union(){
      circle(r=rf);
      for (i=[0:z-1]) rotate(i*360/z)
        polygon([[rf-0.5,-t1],[ra,-t2],[ra,t2],[rf-0.5,t1]]);
    }
    translate([0,0,-1]) cylinder(d=d_arbre+0.2, h=h+2);
  }
}
`;

// 3. Valeurs par défaut (utilisées si le Concepteur oublie une cote)
const DEF = {
  equerre:        { a:40, b:40, l:20, ep:3, trou:4.5, n:2, renfort:false, l_sol:0, l_bout:0 },
