// Petite fonction : met une valeur au bon format OpenSCAD
function fmt(v, defaut) {
  if (Array.isArray(v)) v = v[0];            // une liste -> on garde la 1re valeur
  if (typeof defaut === 'boolean') {
    return (v === true || v === 'true') ? 'true' : 'false';
  }
  const n = Number(v);
  return isNaN(n) ? String(defaut) : String(n);
}

// 6. Encombrement attendu (x, y, z en mm), calcule a partir du plan
function encombrement(forme, p, vols) {
  const n = k => Number(p[k]);
  const larg = () => { const ls = n('l_sol') > 0 ? n('l_sol') : n('l'); const lb = n('l_bout') > 0 ? n('l_bout') : ls; return Math.max(n('l'), ls, lb); };
  switch (forme) {
    case 'equerre':        return [n('a'), larg(), n('b')];
    case 'equerre_tige': {
      const x0 = Math.min(0, n('ep')/2 - n('tige')/2);
      const x1 = Math.max(n('a'), n('ep')/2 + n('tige')/2);
      return [x1 - x0, larg(), n('b') + Math.max(n('tige_l'), Math.max(n('tige'), n('ep')) - 0.5 + 2*n('pas'))];
    }
    case 'sabot':          return [n('w') + 2*n('ep') + 2*n('a'), n('p'), n('h')];
    case 'plaque':         return [n('L'), n('l'), n('ep')];
    case 'gousset':        return [n('a'), n('b'), n('ep')];
    case 'cale':           return [n('l'), n('w'), Math.max(n('h1'), n('h2'))];
    case 'entretoise':     return [n('d_ext'), n('d_ext'), n('h')];
    case 'etrier':         return [n('w') + 2*n('ep') + 2*n('a'), n('l'), n('h') + n('ep')];
    case 'plaque_t':       return [n('L'), n('H'), n('ep')];
    case 'plaque_l':       return [n('a'), n('b'), n('ep')];
    case 'crochet':        return [n('ep') + n('saillie'), Math.max(n('H'), n('pointe')), n('l')];
    case 'support_tube': { const dt = n('d_tube') + 0.4, R = dt/2 + n('ep'); return [2*R + 2*n('aile'), n('l'), dt/2 + R]; }
    case 'clip_tube':    { const dt = n('d_tube') + 0.3, R = dt/2 + n('ep'); return [2*R + 2*n('aile'), n('l'), R * (1 + Math.cos(55*Math.PI/180))]; }
    case 'chape':          return [n('e') + 2*n('ep'), n('l'), n('h')];
    case 'pied_reglable':  return [n('d'), n('d'), n('h')];
    case 'boite':          return [n('L'), n('l'), n('h')];
    case 'couvercle':      return [n('L'), n('l'), n('ep_c') + n('levre')];
    case 'palier':         return [n('L'), n('l'), n('h_roul') + n('ep')];
    case 'support_moteur': return [n('cote'), n('base'), n('cote') + n('ep')];
    case 'collier':        return [n('d_ext'), n('d_ext'), n('h')];
    case 'poulie':         return [n('d'), n('d'), n('h')];
    case 'engrenage':      return null; // dents : encombrement approximatif, pas de controle
  }
  // mode libre : boite englobante des volumes "add" (impossible si rotation)
  const adds = (vols || []).filter(v => v.op !== 'cut');
  if (!adds.length || adds.some(v => v.rot)) return null;
  const lo = [Infinity, Infinity, Infinity], hi = [-Infinity, -Infinity, -Infinity];
  for (const v of adds) {
    const q = (v.pos || [0,0,0]).map(Number);
    let a, b;
    if (v.type === 'cylinder') { const r = Math.max(Number(v.d || 2*v.r || 10), Number(v.d2 || 0)) / 2; a = [q[0]-r, q[1]-r, q[2]]; b = [q[0]+r, q[1]+r, q[2] + Number(v.h || 10)]; }
    else if (v.type === 'sphere') { const r = Number(v.d || 10) / 2; a = q.map(c => c - r); b = q.map(c => c + r); }
    else if (v.type === 'prism') { const P = (v.points || []).map(pt => [Number(pt[0]) + q[0], Number(pt[1]) + q[1]]); a = [Math.min(...P.map(t => t[0])), Math.min(...P.map(t => t[1])), q[2]]; b = [Math.max(...P.map(t => t[0])), Math.max(...P.map(t => t[1])), q[2] + Number(v.h || 4)]; }
    else { const s = (v.size || [10,10,10]).map(Number); a = q; b = q.map((c, i) => c + s[i]); }
    for (let i = 0; i < 3; i++) { lo[i] = Math.min(lo[i], a[i]); hi[i] = Math.max(hi[i], b[i]); }
  }
  return hi.map((h, i) => h - lo[i]);
}

// 4. Construire le code OpenSCAD
let code = '$fn = 64;\n' + LIB + '\n';

let paramsUtilises = null;
if (DEF[forme]) {
  // Forme du catalogue : on mélange défauts + cotes du Concepteur
  // Synonymes que le Concepteur invente parfois
  const ALIAS = { tige_diametre:'tige', diametre_tige:'tige', tige_d:'tige', d_tige:'tige', tige_longueur:'tige_l', longueur_tige:'tige_l', epaisseur:'ep', largeur:'l' };
  const brutP = Object.assign({}, plan.params || {});
  for (const [k, v] of Object.entries(ALIAS)) if (brutP[k] !== undefined && brutP[v] === undefined) { brutP[v] = brutP[k]; delete brutP[k]; }
  const inconnus = Object.keys(brutP).filter(k => !(k in DEF[forme]));
  if (inconnus.length) plan.hypotheses = (plan.hypotheses ? plan.hypotheses + ' ; ' : '') + 'parametres ignores : ' + inconnus.join(', ');
  const params = Object.assign({}, DEF[forme], brutP);
  const args = Object.keys(DEF[forme])
    .map(k => k + '=' + fmt(params[k], DEF[forme][k]))
    .join(', ');
  code += forme + '(' + args + ');\n';
  paramsUtilises = params;
} else {
  // Mode libre : assemblage de volumes
  const vols = plan.volumes || [];
  if (!vols.length) throw new Error('Forme inconnue et aucun volume fourni');

  const num = (x, d) => { const n = Number(Array.isArray(x) ? x[0] : x); return isNaN(n) ? d : n; };
  const vec = (a, d) => (Array.isArray(a) && a.length === 3) ? a.map(x => num(x, 0)) : d;
  const vol = v => {
    const p = vec(v.pos, [0,0,0]);
    const r = vec(v.rot, null);
    const t = 'translate([' + p.join(',') + ']) ' + (r ? 'rotate([' + r.join(',') + ']) ' : '');
    if (v.type === 'cylinder') {
      const d = num(v.d, v.r !== undefined ? num(v.r, 5) * 2 : 10);
      const d2 = v.d2 !== undefined ? num(v.d2, d) : d;
      return t + 'cylinder(d1=' + d + ', d2=' + d2 + ', h=' + num(v.h, 10) + ');';
    }
    if (v.type === 'sphere') {
      return t + 'sphere(d=' + num(v.d, 10) + ');';
    }
    if (v.type === 'prism') {
      const pts = (v.points || []).filter(pt => Array.isArray(pt) && pt.length >= 2);
      if (pts.length < 3) throw new Error('prism : il faut au moins 3 points');
      return t + 'linear_extrude(' + num(v.h, 4) + ') polygon([' + pts.map(pt => '[' + num(pt[0], 0) + ',' + num(pt[1], 0) + ']').join(',') + ']);';
    }
    if (v.type !== 'box') throw new Error('Type de volume inconnu : ' + v.type + '. Types possibles : box, cylinder, sphere, prism.');
    return t + 'cube([' + vec(v.size, [10,10,10]).join(',') + ']);';
  };

  const adds = vols.filter(v => v.op !== 'cut').map(vol);
  const cuts = vols.filter(v => v.op === 'cut').map(vol);
  code += 'difference() {\n union() {\n' + adds.join('\n') + '\n }\n' + cuts.join('\n') + '\n}\n';
}

// 5. Sortie
return [{ json: {
  code,
  nom: plan.nom,
  hypotheses: plan.hypotheses || hyp,
  forme,
  params: paramsUtilises,
  attendu: encombrement(forme, paramsUtilises || {}, plan.volumes),
  nom_base: $('Nom fichier').first().json.nom_base
} }];

// Garde-fou : catalogue en ligne d'abord, sauf demande explicite de concevoir
const fs = require('fs');
const tr = $('Execute Workflow Trigger').first().json;
const direct = /^(oui|true|1|yes)$/i.test(String(tr.concevoir_directement || '').trim());
if (!direct) {
  let recent = false;
  try { recent = (Date.now() - fs.statSync(($env.ARCHI_BASE || '') + '/impression3d/derniere_recherche.json').mtimeMs) < 60 * 60 * 1000; } catch (e) {}
  if (!recent) {
    throw new Error("ETAPE MANQUANTE : cherche d'abord dans les catalogues avec catalogues_3d (action=chercher, mots-cles en anglais) et montre les resultats a l'utilisateur. Seulement si l'utilisateur a demande de concevoir la piece lui-meme, ou si c'est une forme simple du catalogue avec des cotes precises, rappelle cet outil avec concevoir_directement=oui.");
  }
}
// Verifie que la demande n'est pas vide et la met au propre pour le Concepteur
const j = $input.first().json;
const desc = String(j.description || '').trim();
if (desc.length < 5) {
  throw new Error("Description vide : demande a l'utilisateur de decrire la piece avec ses cotes en mm, puis rappelle l'outil.");
}
const cotes = String(j.cotes || '').trim();
const demande = 'Piece demandee : ' + desc + (cotes ? '\nCotes (mm) : ' + cotes : '');
return [{ json: { ...j, demande } }];

// Retour de l'etape 1 vers Archi
const f = $('Fiche apercu').first().json;
const env = $input.first().json || {};
const envoye = !env.error && (env.ok === true || !!env.result || !!env.message_id);
const phrase = envoye
  ? `Voilà l'aperçu BOSS, je te l'ai envoyé avec la fiche : ${f.forme}, encombrement prévu ${f.encomb.replace(/ x /g, ' sur ').replace('mm', 'millimètres')}. Je lance la fabrication ?`
  : `L'aperçu n'a pas pu être envoyé BOSS. J'ai compris : ${f.compris}. Encombrement prévu ${f.encomb}. Je lance la fabrication ?`;
return [{ json: { statut: 'APERCU', apercu_envoye: envoye, nom_fichier: f.nom_base, phrase_pour_utilisateur: phrase, hypotheses: f.hyp } }];

// Etape 1 : prepare la fiche de l'apercu et memorise le plan pour l'etape 2
const fs = require('fs');
const a = $('Assembler SCAD').first().json;
const nf = $('Nom fichier').first().json;
const NOMS = { H:'hauteur', saillie:'saillie', pointe:'pointe', d_tube:'diamètre du tube', aile:'pattes', e:'écartement', d_axe:'trou d\'axe', fond:'fond', ep_c:'épaisseur couvercle', levre:'lèvre', jeu:'jeu', a:'aile au sol', b:'aile verticale', l:'largeur', l_sol:'largeur au sol (angle)', l_bout:'largeur au sol (bout)', ep:'épaisseur', trou:'perçages', n:'trous par aile', renfort:'renfort',
  tige:'diamètre de tige', tige_l:'longueur de tige', pas:'pas', filet:'filetage', w:'largeur intérieure', h:'hauteur', p:'profondeur',
  L:'longueur', nx:'trous en longueur', ny:'trous en largeur', marge:'marge', h1:'bout fin', h2:'bout épais', d_ext:'diamètre extérieur',
  d_int:'diamètre intérieur', d_roul:'diamètre roulement', h_roul:'épaisseur roulement', d_arbre:'diamètre arbre', cote:'côté moteur',
  entraxe:'entraxe', d_centre:'diamètre centrage', base:'base', trou_m:'trous moteur', vis:'trou de vis', d:'diamètre', gorge:'gorge', m:'module', z:'dents' };
const SANS_MM = ['n', 'nx', 'ny', 'z', 'm'];
const val = (k, v) => (typeof v === 'boolean' || v === 'true' || v === 'false') ? ((v === true || v === 'true') ? 'oui' : 'non') : v + (SANS_MM.includes(k) ? '' : ' mm');
const compris = a.params
  ? Object.entries(a.params).map(([k, v]) => (NOMS[k] || k) + ' ' + val(k, v)).join(', ')
  : 'assemblage libre de volumes';
const att = a.attendu ? a.attendu.map(x => +Number(x).toFixed(1)) : null;
const encomb = att ? `${att[0]} x ${att[1]} x ${att[2]} mm` : 'non calculé';
const hyp = String(a.hypotheses || '').trim();

const plan = {
  nom_base: nf.nom_base, chemin_scad: nf.chemin_scad, chemin_stl: nf.chemin_stl,
  forme: a.forme, params: a.params, attendu: a.attendu, hypotheses: hyp, compris, cree_le: new Date().toISOString()
};
const dossier = nf.chemin_scad.replace(/[^/\\]+$/, '');
fs.writeFileSync(nf.chemin_scad.replace(/\.scad$/, '.plan.json'), JSON.stringify(plan, null, 2), 'utf8');
fs.writeFileSync(dossier + 'dernier_apercu.json', JSON.stringify(plan, null, 2), 'utf8');

const fiche = [
  `APERÇU (rien n'est fabriqué) : ${nf.nom_base} (${a.forme})`,
  `J'ai compris : ${compris}`,
  `Encombrement prévu : ${encomb}`,
  hyp ? `Hypothèses : ${hyp}` : '',
  `Réponds « vas-y » pour lancer la fabrication, ou dis-moi quoi changer.`
].filter(Boolean).join('\n').slice(0, 1000);

return [{ json: { fiche, encomb, compris, hyp, nom_base: nf.nom_base, forme: a.forme } }];

// Etape 2 : retrouve le plan valide a l'apercu
const fs = require('fs');
const nf = $('Nom fichier').first().json;
const dossier = nf.chemin_scad.replace(/[^/\\]+$/, '');
const fichierPlan = nf.chemin_scad.replace(/\.scad$/, '.plan.json');
let source = fs.existsSync(fichierPlan) ? fichierPlan : dossier + 'dernier_apercu.json';
if (!fs.existsSync(source)) {
  throw new Error("Aucun apercu trouve : fais d'abord un apercu (mode apercu) avant de lancer la fabrication.");
}
const plan = JSON.parse(fs.readFileSync(source, 'utf8'));
if (!fs.existsSync(plan.chemin_scad)) {
  throw new Error("Le fichier de l'apercu a disparu : refais un apercu.");
}
return [{ json: plan }];
